fun onPrepare(m: Prepare): Message {
    val p = promised
    if (p != null && m.ballot < p) return Reject(m.ballot, p)  // without it: an old proposer's round could still finish
    promised = m.ballot                                         // on disk before replying, or a restart forgets the promise
    return Promise(m.ballot, acceptedBallot, acceptedValue)     // without the accepted value, a chosen value can be overwritten
}

fun onAccept(m: Accept): Message {
    val p = promised
    if (p != null && m.ballot < p) return Reject(m.ballot, p)  // without it: accept a ballot you promised to ignore
    promised = m.ballot
    acceptedBallot = m.ballot
    acceptedValue = m.value
    return Accepted(m.ballot, m.value)
}

fun chooseValue(own: String, promises: Collection<Promise>): String =
    promises.filter { it.accepted != null }.maxByOrNull { it.accepted!! }?.value ?: own   // the safety rule
